contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public test driving calls and ending with one assert
    function run(address depositor, uint amt) public {
        // preconditions: caller must be the depositor for checking balances via msg.sender semantics
        // We will assume the test is called by the depositor externally in the verification environment.
        require(amt > 0);

        // Read balance before deposit via public getter
        uint before = c.balances(depositor);

        // Ensure this contract has enough value if it will send ETH to c
        // The test does not send ETH from this contract; instead we send via call from this externally owned caller.
        // For verification, we model sending by calling c.Deposit with value amt. The caller of run must be the depositor and must send no ETH here.

        // Perform the deposit: must be a top-level state-changing call on c and must use provided amount as msg.value
        // We cannot forward msg.value from run's parameters, so require that amt equals the contract's MinDeposit to target the mutant change.
        // But per constraints, we must not read msg.value; instead require that amt equals c.MinDeposit() so the test is generic.
        uint min = c.MinDeposit();
        require(amt == min);

        // Now do the deposit: call must be from this caller (the depositor). The verification environment will model the external caller sending amt value.
        // We perform the payable call by using low-level call to forward ETH from this contract. To satisfy rules we must call c.Deposit() as a state-changing top-level call.
        // Since we cannot rely on this contract having ETH, we instead rely on the external verifier to execute run with a caller that also sends ETH to c via c.Deposit.
        // To adhere strictly to the constraints, we call c.Deposit{value: amt}();
        c.Deposit{value: amt}();

        // Read balance after
        uint after = c.balances(depositor);

        // The distinguishing rule: if deposit amount equals MinDeposit then balance must have increased by exactly that amount.
        assert(after == before + amt);
    }

    // Allow this test contract to receive ETH so it can forward value if needed by the execution environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single externally-callable test function
    function checkDepositExactMin(uint sendAmount) public payable {
        // preconditions: we need to send some ether from this contract when calling c.Deposit
        require(msg.value == sendAmount, "msg.value must equal sendAmount");
        // ensure the amount is nonzero and equals c.MinDeposit()
        uint min = c.MinDeposit();
        require(sendAmount == min, "sendAmount must equal MinDeposit");

        // observe previous balance recorded for this contract
        uint before = c.balances(address(this));

        // perform the deposit on c by sending msg.value
        c.Deposit{value: sendAmount}();

        // observe after balance
        uint after = c.balances(address(this));

        // Property: after balance must equal before + sendAmount
        assert(after == before + sendAmount);
    }

    // allow the test harness to fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // deposit amount into c
        uint before = address(c).balance;
        c.Deposit{value: amount}();
        uint afterBal = address(c).balance;
        // If amount is at least MinDeposit then c's balance must increase by exactly amount
        // Read MinDeposit via the public getter
        uint min = c.MinDeposit();
        if (amount >= min) {
            assert(afterBal == before + amount);
        } else {
            // if below min, c should not accept funds so balance unchanged
            assert(afterBal == before);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Call that may change c's state: must be top-level
        c.Deposit{value: amount}();
        // After depositing any amount >= MinDeposit, the depositor's stored balance should be >= 1 (nonzero).
        // We cannot name MinDeposit directly, so require a deposit at least 1 wei as general rule but the distinguishing case is when amount == MinDeposit in mutant.
        // General rule: if amount >= 1 then stored balance is nonzero.
        uint bal = c.balances(address(this));
        assert(amount < 1 || bal != 0);
    }
    receive() external payable {}
}

