contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Exclude the problematic cases where amount is less than C.MinDeposit but >= 1,
        // by ensuring amount is either < 1 or strictly greater than c.MinDeposit().
        // We may only call view functions inside require, MinDeposit is a public uint so this is allowed.
        require(amount < 1 || amount > c.MinDeposit());
        // Call that may change c's state: must be top-level
        c.Deposit{value: amount}();
        // After depositing any amount >= MinDeposit, the depositor's stored balance should be >= 1 (nonzero).
        // We cannot name MinDeposit directly in the assertion, so keep the original form.
        uint bal = c.balances(address(this));
        assert(amount < 1 || bal != 0);
    }
    receive() external payable {}
}
